function parseChunks(txt, file) {
  const out = [];
  const parts = txt.split(/^##\s*CHUNK:\s*/m).slice(1);
  for (const p of parts) {
    const nl = p.indexOf('\n');
    const id = p.slice(0, nl).trim();
    const rest = p.slice(nl + 1);
    const sep = rest.search(/^---\s*$/m);
    const head = sep >= 0 ? rest.slice(0, sep) : '';
    const body = (sep >= 0 ? rest.slice(sep).replace(/^---\s*/, '') : rest).trim();
    const meta = {};
    for (const line of head.split('\n')) {
      const m = line.match(/^\s*([a-z_]+)\s*:\s*(.*)$/i);
      if (m) meta[m[1].toLowerCase()] = m[2].trim();
    }
    out.push({ chunk_id: id, file, source: meta.source || '', section: meta.section || '', title: meta.title || '',
      jurisdiction: meta.jurisdiction || '', topic: meta.topic || '', keywords: meta.keywords || '',
      url: meta.url || '', accessed: meta.accessed || '', text: body });
  }
  return out;
}

async function readAll(self, items) {
  const files = [];
  for (let i = 0; i < items.length; i++) {
    const b = items[i].binary && items[i].binary.data;
    if (!b) continue;
    const buf = await self.helpers.getBinaryDataBuffer(i, 'data');
    files.push({ fileName: b.fileName, directory: b.directory || '', text: buf.toString('utf8') });
  }
  return files;
}

const chunks = []; let tests = null;
for (const f of await readAll(this, $input.all())) {
  if (f.fileName === 'retrieval-tests.json') { tests = JSON.parse(f.text); continue; }
  chunks.push(...parseChunks(f.text.replace(/<!--[\s\S]*?-->/g, ''), f.fileName));
}
if (!tests) throw new Error('config/retrieval-tests.json not found');
return chunks.map(ch => ({ json: { ...ch, embed_text: `${ch.title}\nKeywords: ${ch.keywords}\n${ch.text}`, _tests: tests } }));

function bm25Rank(chunks, query, k) {
  const STOP = new Set('a an and are as at be by for from has have in is it its of on or that the to was were will with this those these been their there what which who how do does not no can may must should'.split(' '));
  const tok = (s) => String(s).toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 1 && !STOP.has(w));
  const docs = chunks.map(ch => tok(`${ch.title} ${ch.title} ${ch.keywords} ${ch.keywords} ${ch.topic} ${ch.text}`));
  const N = docs.length, avg = docs.reduce((s, d) => s + d.length, 0) / Math.max(N, 1);
  const df = {}; for (const d of docs) for (const w of new Set(d)) df[w] = (df[w] || 0) + 1;
  const k1 = 1.5, b = 0.75, qt = [...new Set(tok(query))];
  return chunks.map((ch, i) => {
    const tf = {}; for (const w of docs[i]) tf[w] = (tf[w] || 0) + 1;
    let s = 0;
    for (const w of qt) { if (!tf[w]) continue; const idf = Math.log((N - df[w] + 0.5) / (df[w] + 0.5) + 1); s += idf * (tf[w] * (k1 + 1)) / (tf[w] + k1 * (1 - b + b * docs[i].length / avg)); }
    return { id: ch.chunk_id, s };
  }).filter(x => x.s > 0).sort((x, y) => y.s - x.s).slice(0, k).map(x => x.id);
}

const K = 4;
const chunks = $('Load KB and tests').all().map(i => i.json);
const queries = $('Test queries').all().map(i => i.json);
// Semantic search returns exactly K results per query (in query order) when the KB has >= K chunks.
// Inside a Code node n8n re-numbers item links, so results are grouped by position and the count is asserted.
const items = $input.all();
if (items.length !== K * queries.length) throw new Error(`Expected ${K * queries.length} semantic results (${K} per query), got ${items.length}. Does the KB have at least ${K} chunks?`);
const semantic = queries.map((q, qi) => items.slice(qi * K, qi * K + K).map(it => it.json.document && it.json.document.metadata && it.json.document.metadata.chunk_id).filter(Boolean));
const rrf = (lists) => { const sc = {}; for (const l of lists) l.forEach((id, r) => { sc[id] = (sc[id] || 0) + 1 / (60 + r + 1); });
  return Object.entries(sc).sort((a, b) => b[1] - a[1]).slice(0, K).map(([id]) => id); };
const metrics = (top, exp) => {
  const rel = top.filter(id => exp.includes(id));
  const first = top.findIndex(id => exp.includes(id));
  return { hit: rel.length > 0 ? 1 : 0, recall: exp.length ? rel.length / exp.length : 0, precision: top.length ? rel.length / K : 0, rr: first >= 0 ? 1 / (first + 1) : 0 };
};
const rows = queries.map((q, i) => {
  const kw = bm25Rank(chunks, q.query, K), se = semantic[i].slice(0, K), hy = rrf([kw, se]);
  return { qn: q.qn, query: q.query, expected: q.expected, keyword: { top: kw, ...metrics(kw, q.expected) },
           semantic: { top: se, ...metrics(se, q.expected) }, hybrid: { top: hy, ...metrics(hy, q.expected) } };
});
const avg = (m, f) => Math.round(1000 * rows.reduce((s, r) => s + r[m][f], 0) / Math.max(rows.length, 1)) / 1000;
const summary = {};
for (const m of ['keyword', 'semantic', 'hybrid']) summary[m] = { hit_rate: avg(m, 'hit'), mean_recall: avg(m, 'recall'), mean_precision: avg(m, 'precision'), mrr: avg(m, 'rr') };
const s = $('Settings').first().json;
const report = { label: { platform: 'n8n (local) + Google Gemini embeddings', embedding_model: s.embedding_model, generated_at: new Date().toISOString(),
                          execution_id: $execution.id, context: `Retrieval check: ${rows.length} test queries, top-${K}, ${chunks.length} KB chunks` },
                 k: K, kb_chunks: chunks.length, summary, queries: rows };
return [{ json: { report_file: `${s.data_dir}/logs/retrieval-check__exec${$execution.id}.json`, report } }];
